@dataclass(frozen=True)
class OtoTiming:
    offset: float
    consonant: float
    cutoff: float
    preutterance: float
    overlap: float

    def as_tuple(self) -> tuple[float, float, float, float, float]:
        return (self.offset, self.consonant, self.cutoff, self.preutterance, self.overlap)


@dataclass(frozen=True)
class OtoTemplateRow:
    wav: str
    alias: str
    timing: OtoTiming
    raw_line: str = ""
    source_row_index: int = -1
    expected_phone_indices: tuple[int, ...] | None = None


@dataclass(frozen=True)
class OtoAnchor:
    anchor_abs_ms: float
    score: float = 1.0
    role: str = "cv_boundary"
    frame_index: int | None = None
    refined_from_abs_ms: float | None = None
    local_refine_delta_ms: float | None = None
    local_refine_margin: float | None = None
    local_refine_window_ms: float | None = None
    vowel_nucleus_abs_ms: float | None = None
    vowel_start_abs_ms: float | None = None
    vowel_end_abs_ms: float | None = None
    # Absolute onset of the leading consonant for headed (C->V) anchors. Used so
    # the generated offset reaches back far enough to include the whole
    # consonant instead of clipping its attack.
    consonant_onset_abs_ms: float | None = None
    previous_vowel_end_abs_ms: float | None = None
    next_onset_abs_ms: float | None = None
    next_vowel_abs_ms: float | None = None
    boundary_confidence: float = 0.0
    nucleus_confidence: float = 0.0
    expected_phone: str | None = None
    expected_phone_index: int | None = None
    slot_index: int | None = None
    source_event_label: str | None = None
    warnings: tuple[str, ...] = ()


@dataclass(frozen=True)
class AliasTargetCandidate:
    phone_index: int | None
    score: float
    reason: str


@dataclass(frozen=True)
class OtoAdapterConfig:
    mode: str = "template-preserve"
    language: str = "japanese"
    format_type: str = "CV"
    alias_type: str = "auto"
    min_anchor_score: float = 0.05
    max_anchor_shift_ms: float = 160.0
    pre_target_ms: float = 120.0
    ovl_gap_ms: float = 35.0
    cons_gap_ms: float = 40.0
    tail_margin_ms: float = 50.0
    previous_tail_keep_ms: float = 40.0
    vowel_nucleus_left_ratio: float = 0.46
    vowel_nucleus_right_ratio: float = 0.54
    vc_pre_max_ms: float = 80.0
    preserve_source_timing: bool = False


@dataclass(frozen=True)
class AdaptedOtoRow:
    wav: str
    alias: str
    timing: OtoTiming
    source_timing: OtoTiming | None
    anchor: OtoAnchor | None
    mode: str
    warnings: tuple[str, ...] = ()
    applied_rules: tuple[str, ...] = ()

    def format_line(self) -> str:
        return format_oto_line(self.wav, self.alias, self.timing)

    def to_json_dict(self) -> dict:
        payload = {
            "wav": self.wav,
            "alias": self.alias,
            "mode": self.mode,
            "timing": timing_to_dict(self.timing),
            "absolute": absolute_oto_positions(self.timing),
            "warnings": list(self.warnings),
            "applied_rules": list(self.applied_rules),
        }
        if self.source_timing is not None:
            payload["source_timing"] = timing_to_dict(self.source_timing)
            payload["source_absolute"] = absolute_oto_positions(self.source_timing)
        if self.anchor is not None:
            payload["anchor"] = {
                "anchor_abs_ms": self.anchor.anchor_abs_ms,
                "score": self.anchor.score,
                "role": self.anchor.role,
                "frame_index": self.anchor.frame_index,
                "refined_from_abs_ms": self.anchor.refined_from_abs_ms,
                "local_refine_delta_ms": self.anchor.local_refine_delta_ms,
                "local_refine_margin": self.anchor.local_refine_margin,
                "local_refine_window_ms": self.anchor.local_refine_window_ms,
                "vowel_nucleus_abs_ms": self.anchor.vowel_nucleus_abs_ms,
                "vowel_start_abs_ms": self.anchor.vowel_start_abs_ms,
                "vowel_end_abs_ms": self.anchor.vowel_end_abs_ms,
                "previous_vowel_end_abs_ms": self.anchor.previous_vowel_end_abs_ms,
                "next_onset_abs_ms": self.anchor.next_onset_abs_ms,
                "next_vowel_abs_ms": self.anchor.next_vowel_abs_ms,
                "boundary_confidence": self.anchor.boundary_confidence,
                "nucleus_confidence": self.anchor.nucleus_confidence,
                "expected_phone": self.anchor.expected_phone,
                "expected_phone_index": self.anchor.expected_phone_index,
                "slot_index": self.anchor.slot_index,
                "source_event_label": self.anchor.source_event_label,
                "warnings": list(self.anchor.warnings),
            }
        return payload


def load_oto_template_rows(path: str | Path) -> list[OtoTemplateRow]:
    rows: list[OtoTemplateRow] = []
    for line_index, line in enumerate(read_text_with_fallback(str(path)).splitlines()):
        row = parse_template_oto_line(line, source_row_index=line_index)
        if row is not None:
            rows.append(row)
    return rows


def load_oto_template_rows_alias_only(path: str | Path) -> list[OtoTemplateRow]:
    rows = load_oto_template_rows(path)
    return [
        row
        if _is_nonphonetic_special_alias(row.alias)
        else replace(
            row,
            timing=OtoTiming(
                offset=0.0,
                consonant=0.0,
                cutoff=0.0,
                preutterance=0.0,
                overlap=0.0,
            ),
        )
        for row in rows
    ]


def parse_template_oto_line(line: str, *, source_row_index: int = -1) -> OtoTemplateRow | None:
    parsed = parse_oto_line(line)
    if not parsed:
        return None
    return OtoTemplateRow(
        wav=str(parsed["wav"]),
        alias=str(parsed["alias"]),
        timing=OtoTiming(
            offset=float(parsed["offset"]),
            consonant=float(parsed["cons"]),
            cutoff=float(parsed["cutoff"]),
            preutterance=float(parsed["pre"]),
            overlap=float(parsed["ovl"]),
        ),
        raw_line=line.rstrip("\n"),
        source_row_index=int(source_row_index),
    )


def adapt_template_row(
    row: OtoTemplateRow,
    anchor: OtoAnchor | None,
    *,
    file_duration_ms: float,
    config: OtoAdapterConfig | None = None,
) -> AdaptedOtoRow:
    cfg = config or OtoAdapterConfig()
    if not cfg.preserve_source_timing:
        return _bootstrap_template_alias_only(
            row,
            anchor,
            file_duration_ms=file_duration_ms,
            config=cfg,
        )
    if anchor is None:
        if _is_degenerate_timing(row.timing):
            fallback_anchor = _fallback_anchor_for_row(
                row,
                file_duration_ms=file_duration_ms,
                config=cfg,
                warning="missing_anchor_zero_template",
            )
            boot = bootstrap_row(
                row.wav,
                row.alias,
                fallback_anchor,
                file_duration_ms=file_duration_ms,
                config=cfg,
            )
            return replace(
                boot,
                source_timing=row.timing,
                mode="template-bootstrap",
                warnings=tuple(dict.fromkeys((*boot.warnings, "missing_anchor_zero_template"))),
            )
        return _kept_row(row, cfg, "missing_anchor")
    if _is_degenerate_timing(row.timing):
        boot = bootstrap_row(
            row.wav,
            row.alias,
            anchor,
            file_duration_ms=file_duration_ms,
            config=cfg,
        )
        bootstrap_warnings = [*boot.warnings, "zero_template_bootstrap"]
        if anchor.score < cfg.min_anchor_score:
            bootstrap_warnings.append(f"low_anchor_score:{anchor.score:.3f}")
        return replace(
            boot,
            source_timing=row.timing,
            mode="template-bootstrap",
            warnings=tuple(dict.fromkeys(bootstrap_warnings)),
        )

    if anchor.score < cfg.min_anchor_score:
        return _kept_row(row, cfg, f"low_anchor_score:{anchor.score:.3f}")

    current_anchor = row.timing.offset + row.timing.preutterance
    shift = anchor.anchor_abs_ms - current_anchor
    warnings = list(anchor.warnings)
    allow_large_slot_shift = "slot_decoded_event" in anchor.warnings
    if abs(shift) > cfg.max_anchor_shift_ms and not allow_large_slot_shift:
        limited = _clamp(shift, -cfg.max_anchor_shift_ms, cfg.max_anchor_shift_ms)
        anchor = replace(anchor, anchor_abs_ms=current_anchor + limited)
        warnings.append(f"anchor_shift_limited:{shift:.1f}->{limited:.1f}")
    elif abs(shift) > cfg.max_anchor_shift_ms and allow_large_slot_shift:
        warnings.append(f"slot_anchor_shift_allowed:{shift:.1f}")

    alias_type = _adaptation_alias_type(row.alias, cfg.alias_type, anchor)
    profile = get_anchor_profile(cfg.language, cfg.format_type, alias_type)
    ctx = AnchorTimingContext(
        file_duration_ms=file_duration_ms,
        timeline_start_ms=0.0,
        timeline_end_ms=file_duration_ms,
        anchor_abs_ms=anchor.anchor_abs_ms,
        next_onset_abs_ms=anchor.next_onset_abs_ms,
        next_vowel_abs_ms=anchor.next_vowel_abs_ms,
        alias_type=alias_type,
        language=cfg.language,
        format_type=cfg.format_type,
        mapping_confidence=max(0.0, min(1.0, anchor.score)),
    )
    result = apply_anchor_lock(row.timing.as_tuple(), ctx, profile)
    timing = OtoTiming(
        offset=result.offset,
        consonant=result.consonant,
        cutoff=result.cutoff,
        preutterance=result.pre,
        overlap=result.ovl,
    )
    if profile is None:
        timing = _direct_anchor_shift(row.timing, anchor.anchor_abs_ms)
        warnings.append("profile_missing_direct_anchor")
    timing, timing_warnings = _validate_timing_with_warnings(timing, file_duration_ms=file_duration_ms)
    warnings.extend(timing_warnings)
    return AdaptedOtoRow(
        wav=row.wav,
        alias=row.alias,
        timing=timing,
        source_timing=row.timing,
        anchor=anchor,
        mode="template-preserve",
        warnings=tuple(dict.fromkeys(warnings)),
        applied_rules=tuple(result.applied_rules),
    )


def _adaptation_alias_type(alias: str, default_alias_type: str, anchor: OtoAnchor | None) -> str:
    role = str(getattr(anchor, "role", "") or "").strip().lower()
    if role in {"cv", "cv_head", "vcv", "vc", "vv", "v"}:
        return role
    return _alias_type_for_row(alias, default_alias_type)


def bootstrap_row(
    wav: str,
    alias: str,
    anchor: OtoAnchor | None,
    *,
    file_duration_ms: float,
    config: OtoAdapterConfig | None = None,
) -> AdaptedOtoRow:
    cfg = config or OtoAdapterConfig(mode="bootstrap")
    alias_type = _adaptation_alias_type(alias, cfg.alias_type, anchor)
    pre_target_ms, ovl_gap_ms, cons_gap_ms = _bootstrap_role_profile(cfg, alias_type)
    if anchor is None:
        timing, timing_warnings = _validate_timing_with_warnings(
            OtoTiming(0.0, pre_target_ms + cons_gap_ms, -max(180.0, file_duration_ms), pre_target_ms, max(0.0, pre_target_ms - ovl_gap_ms)),
            file_duration_ms=file_duration_ms,
        )
        return AdaptedOtoRow(
            wav=wav,
            alias=alias,
            timing=timing,
            source_timing=None,
            anchor=None,
            mode="bootstrap",
            warnings=tuple(dict.fromkeys(("missing_anchor", *timing_warnings))),
        )

    if _is_terminal_silence_alias(alias):
        return _bootstrap_terminal_silence_row(
            wav,
            alias,
            anchor,
            file_duration_ms=file_duration_ms,
            config=cfg,
        )

    raw_anchor_abs = _clamp(anchor.anchor_abs_ms, 0.0, file_duration_ms)
    anchor_abs, anchor_adjust_warnings = _bootstrap_anchor_abs_ms(
        cfg,
        alias_type,
        anchor,
        alias=alias,
        file_duration_ms=file_duration_ms,
    )
    anchor_lead_ms = max(0.0, raw_anchor_abs - anchor_abs)
    anchor_warnings = list(anchor.warnings)
    anchor_warnings.extend(anchor_adjust_warnings)
    vc_pre_cap_ms = max(12.0, float(cfg.vc_pre_max_ms))
    if alias_type == "v":
        compact_cvvc_vowel = _bootstrap_japanese_cvvc_stale_standalone_vowel_row(
            wav,
            alias,
            anchor,
            anchor_abs,
            file_duration_ms=file_duration_ms,
            config=cfg,
        )
        if compact_cvvc_vowel is not None:
            return compact_cvvc_vowel
        nucleus_abs = _clamp(anchor.vowel_nucleus_abs_ms if anchor.vowel_nucleus_abs_ms is not None else anchor_abs, 0.0, file_duration_ms)
        vowel_start = _clamp(
            anchor.vowel_start_abs_ms if anchor.vowel_start_abs_ms is not None else max(0.0, nucleus_abs - 120.0),
            0.0,
            file_duration_ms,
        )
        vowel_end = _clamp(
            anchor.vowel_end_abs_ms if anchor.vowel_end_abs_ms is not None else min(file_duration_ms, nucleus_abs + 180.0),
            vowel_start,
            file_duration_ms,
        )
        left_span = max(28.0, nucleus_abs - vowel_start)
        right_span = max(36.0, vowel_end - nucleus_abs)
        pre = max(56.0, left_span * (1.0 + max(0.0, min(1.0, cfg.vowel_nucleus_left_ratio))))
        offset = max(nucleus_abs - pre, 0.0)
        overlap = max(0.0, pre - max(18.0, left_span * 0.72))
        consonant = pre + max(24.0, right_span * max(0.35, min(1.0, cfg.vowel_nucleus_right_ratio)))
        cutoff_trim, cutoff_warnings = _bootstrap_cutoff_trim_ms(
            cfg,
            "v",
            max(consonant + 8.0, (vowel_end - offset) + cfg.tail_margin_ms),
            min_trim_ms=consonant + 8.0,
            file_duration_ms=file_duration_ms,
        )
        cutoff = -cutoff_trim
        timing, timing_warnings = _validate_timing_with_warnings(
            OtoTiming(offset=offset, consonant=consonant, cutoff=cutoff, preutterance=pre, overlap=overlap),
            file_duration_ms=file_duration_ms,
        )
        return AdaptedOtoRow(
            wav=wav,
            alias=alias,
            timing=timing,
            source_timing=None,
            anchor=anchor,
            mode="bootstrap",
            warnings=tuple(dict.fromkeys((*anchor.warnings, *cutoff_warnings, *timing_warnings))),
        )
    elif alias_type == "vcv":
        prev_end = anchor.previous_vowel_end_abs_ms
        if prev_end is None:
            prev_end = max(0.0, anchor_abs - cfg.pre_target_ms)
        max_prev_end = max(0.0, anchor_abs - max(24.0, cfg.pre_target_ms))
        if float(prev_end) > max_prev_end:
            anchor_warnings.append(f"vcv_previous_vowel_end_clamped:{float(prev_end):.1f}->{max_prev_end:.1f}")
            prev_end = max_prev_end
        offset = max(float(prev_end) - cfg.previous_tail_keep_ms, 0.0)
    elif alias_type == "vc":
        vc_pre_target_ms, vc_context_warnings = _cvvc_vc_context_pre_ms(cfg, anchor, anchor_abs)
        anchor_warnings.extend(vc_context_warnings)
        vc_pre_cap_ms = max(vc_pre_cap_ms, vc_pre_target_ms)
        offset = max(anchor_abs - vc_pre_target_ms, 0.0)
    elif alias_type == "cv":
        cv_pre_target_ms, cv_context_warnings = _cvvc_cv_context_pre_ms(cfg, anchor, anchor_abs)
        anchor_warnings.extend(cv_context_warnings)
        offset = max(anchor_abs - cv_pre_target_ms, 0.0)
    else:
        offset = max(anchor_abs - cfg.pre_target_ms, 0.0)
    pre = max(anchor_abs - offset, 0.0)
    if alias_type == "vc":
        pre = min(pre, vc_pre_cap_ms)
        offset = max(anchor_abs - pre, 0.0)
    elif alias_type in {"cv_head", "vcv", "vv"}:
        target_pre = min(float(pre_target_ms), anchor_abs)
        offset = max(anchor_abs - target_pre, 0.0)
        pre = max(anchor_abs - offset, 0.0)
    if alias_type in {"cv", "cv_head", "vcv"}:
        offset, pre, consonant_include_warnings = _include_leading_consonant_in_offset(
            offset,
            pre,
            anchor_abs,
            anchor.consonant_onset_abs_ms,
        )
        anchor_warnings.extend(consonant_include_warnings)
    overlap = max(0.0, pre - ovl_gap_ms)
    consonant = pre + cons_gap_ms
    cutoff_warnings: tuple[str, ...] = ()
    if alias_type == "vc":
        cut_gap = _role_cut_gap_ms(cfg, alias_type)
        cutoff = -(max(consonant + 8.0, consonant + cut_gap))
    else:
        vowel_end = anchor.vowel_end_abs_ms if anchor.vowel_end_abs_ms is not None else min(file_duration_ms, anchor_abs + 180.0)
        raw_cutoff_trim = max(consonant + 8.0, float(vowel_end) - offset + cfg.tail_margin_ms - anchor_lead_ms)
        raw_cutoff_trim, cvvc_head_cutoff_warnings = _cvvc_cv_head_cutoff_trim_ms(
            cfg,
            alias_type,
            alias,
            anchor,
            raw_cutoff_trim,
            min_trim_ms=consonant + 8.0,
            offset_ms=offset,
            file_duration_ms=file_duration_ms,
        )
        cutoff_trim, cutoff_warnings = _bootstrap_cutoff_trim_ms(
            cfg,
            alias_type,
            raw_cutoff_trim,
            min_trim_ms=consonant + 8.0,
            file_duration_ms=file_duration_ms,
        )
        cutoff_warnings = (*cvvc_head_cutoff_warnings, *cutoff_warnings)
        cutoff = -cutoff_trim
    timing, timing_warnings = _validate_timing_with_warnings(
        OtoTiming(offset=offset, consonant=consonant, cutoff=cutoff, preutterance=pre, overlap=overlap),
        file_duration_ms=file_duration_ms,
    )
    return AdaptedOtoRow(
        wav=wav,
        alias=alias,
        timing=timing,
        source_timing=None,
        anchor=anchor,
        mode="bootstrap",
        warnings=tuple(dict.fromkeys((*anchor_warnings, *cutoff_warnings, *timing_warnings))),
    )


def anchors_from_prediction(
    posterior: FramePosterior,
    decoded_events: Sequence[DecodedEvent | Mapping[str, object]],
) -> list[OtoAnchor]:
    anchors: list[OtoAnchor] = []
    previous_vowel_end: float | None = None
    pending_consonant_onset: float | None = None
    decoded = [_event_to_dict(event) for event in decoded_events]
    for idx, event in enumerate(decoded):
        if event["label"] not in {"cv_boundary", "phone_change", "vowel_nucleus", "vv_boundary"}:
            continue
        anchor_ms = float(event["time_ms"])
        # A phone_change immediately preceding a cv_boundary marks the leading
        # consonant onset for that CV; remember it so the CV anchor can keep the
        # consonant inside its offset window.
        if str(event["label"]) == "phone_change":
            pending_consonant_onset = anchor_ms
        consonant_onset_abs = None
        if str(event["label"]) == "cv_boundary" and pending_consonant_onset is not None:
            if 0.0 <= float(pending_consonant_onset) < anchor_ms:
                consonant_onset_abs = float(pending_consonant_onset)
        if str(event["label"]) != "phone_change":
            pending_consonant_onset = None
        span = estimate_vowel_span(posterior, anchor_ms)
        nucleus_time, nucleus_conf, nucleus_warnings = estimate_vowel_nucleus(
            posterior,
            anchor_ms,
            vowel_start_abs_ms=span.get("vowel_start_abs_ms"),
            vowel_end_abs_ms=span.get("vowel_end_abs_ms"),
        )
        next_vowel = next((float(item["time_ms"]) for item in decoded[idx + 1 :] if item["label"] == "vowel_nucleus"), None)
        warning = "slot_decoded_event" if event.get("expected_phone") else "decoded_event"
        role = str(event["label"])
        boundary_conf = _anchor_boundary_confidence(posterior, anchor_ms, role=role)
        if role == "vowel_nucleus":
            selected_nucleus = anchor_ms
            selected_nucleus_conf = max(float(event.get("score") or 0.0), nucleus_conf)
        else:
            selected_nucleus = nucleus_time if nucleus_time is not None else next_vowel
            selected_nucleus_conf = nucleus_conf
        anchor_warnings = [warning, f"decoded_order:{idx}"]
        event_source = str(event.get("source") or "").strip()
        if event_source:
            anchor_warnings.append(f"event_source:{event_source}")
        anchor_warnings.extend(nucleus_warnings)
        if selected_nucleus_conf < 0.35:
            anchor_warnings.append(f"low_nucleus_confidence:{selected_nucleus_conf:.3f}")
        if boundary_conf < 0.30:
            anchor_warnings.append(f"low_boundary_confidence:{boundary_conf:.3f}")
        anchor = OtoAnchor(
            anchor_abs_ms=anchor_ms,
            score=float(event.get("score") or 0.0),
            role=role,
            frame_index=event.get("frame_index"),
            vowel_nucleus_abs_ms=selected_nucleus,
            vowel_start_abs_ms=span.get("vowel_start_abs_ms"),
            vowel_end_abs_ms=span.get("vowel_end_abs_ms"),
            consonant_onset_abs_ms=consonant_onset_abs,
            previous_vowel_end_abs_ms=previous_vowel_end,
            next_vowel_abs_ms=next_vowel,
            boundary_confidence=boundary_conf,
            nucleus_confidence=selected_nucleus_conf,
            expected_phone=str(event.get("expected_phone") or "") or None,
            expected_phone_index=_int_or_none(event.get("expected_phone_index")),
            slot_index=_int_or_none(event.get("slot_index")),
            source_event_label=role,
            warnings=tuple(anchor_warnings),
        )
        anchors.append(anchor)
        previous_vowel_end = anchor.vowel_end_abs_ms or previous_vowel_end
    return anchors


def assign_template_row_anchors(
    posterior: FramePosterior,
    decoded_events: Sequence[DecodedEvent | Mapping[str, object]],
    template_rows: Sequence[OtoTemplateRow],
    *,
    min_score: float = 0.03,
    use_source_timing_prior: bool = True,
    expected_phones: Sequence[str] | None = None,
    language: str = "",
) -> list[OtoAnchor | None]:
    if not template_rows:
        return []
    times = np.asarray(posterior.times_ms, dtype=np.float32)
    if times.size == 0:
        return [None for _ in template_rows]
    duration_ms = float(max(times[-1], 1.0))
    candidates = _posterior_anchor_candidates(posterior, min_score=min_score)
    for event in anchors_from_prediction(posterior, decoded_events):
        candidates.append(event)
    candidates.sort(key=lambda item: (item.anchor_abs_ms, -item.score))

    used: set[int] = set()
    out: list[OtoAnchor | None] = []
    last_time = -float("inf")
    last_target_phone_index: int | None = None
    alias_targets = _alias_targets_from_template_rows_or_dp(template_rows, expected_phones or (), language=language)
    row_roles = [_alias_type_for_row(row.alias, "auto") for row in template_rows]
    decoded_count = sum(1 for item in candidates if "slot_decoded_event" in item.warnings)
    for row_idx, row in enumerate(template_rows):
        base_role = row_roles[row_idx] if row_idx < len(row_roles) else _alias_type_for_row(row.alias, "auto")
        target_phone_index = alias_targets[row_idx] if row_idx < len(alias_targets) else None
        role = _contextual_alias_role_for_row_sequence(
            template_rows,
            row_roles,
            row_idx,
            expected_phones or (),
            target_phone_index,
            base_role=base_role,
            language=language,
        )
        preferred_labels = _preferred_event_labels_for_alias(row.alias, role)
        original_target_phone_index = target_phone_index
        original_target_phone = (
            str((expected_phones or ())[int(original_target_phone_index)])
            if original_target_phone_index is not None
            and 0 <= int(original_target_phone_index) < len(expected_phones or ())
            else ""
        )
        expected_time = _template_expected_time(
            row,
            row_idx,
            len(template_rows),
            duration_ms,
            use_source_timing_prior=use_source_timing_prior,
        )
        best_idx: int | None = None
        best_score = -1e9
        rejected_leading_noise = False
        for cand_idx, candidate in enumerate(candidates):
            if cand_idx in used:
                continue
            same_target_reuse = (
                target_phone_index is not None
                and candidate.expected_phone_index == target_phone_index
                and last_target_phone_index == target_phone_index
            )
            target_backtrack = (
                target_phone_index is not None
                and last_target_phone_index is not None
                and target_phone_index < last_target_phone_index
            )
            if candidate.anchor_abs_ms + 1e-5 < last_time + 4.0 and not same_target_reuse and not target_backtrack:
                continue
            if target_phone_index is not None and candidate.expected_phone_index != target_phone_index:
                continue
            if _is_likely_leading_sonorant_noise_anchor(
                candidate,
                target_phone_index=target_phone_index,
                target_phone=original_target_phone,
                expected_time_ms=expected_time,
                duration_ms=duration_ms,
                posterior=posterior,
            ):
                rejected_leading_noise = True
                continue
            label_bonus = 0.25 if candidate.role in preferred_labels else -0.05
            if "slot_decoded_event" in candidate.warnings:
                decoded_bonus = 0.85 if candidate.expected_phone_index == target_phone_index else 0.62
            elif "decoded_event" in candidate.warnings:
                decoded_bonus = 0.35
            else:
                decoded_bonus = 0.0
            distance_penalty = abs(candidate.anchor_abs_ms - expected_time) / duration_ms
            order_penalty = _decoded_order_penalty(
                candidate,
                row_idx=row_idx,
                row_count=len(template_rows),
                decoded_count=decoded_count,
            )
            score = float(candidate.score) + label_bonus + decoded_bonus - (0.90 * distance_penalty) - order_penalty
            if score > best_score:
                best_score = score
                best_idx = cand_idx
        if best_idx is None:
            if target_phone_index is not None:
                target_phone_index = None
                for cand_idx, candidate in enumerate(candidates):
                    if cand_idx in used:
                        continue
                    if candidate.anchor_abs_ms + 1e-5 < last_time + 4.0:
                        continue
                    if _is_likely_leading_sonorant_noise_anchor(
                        candidate,
                        target_phone_index=original_target_phone_index,
                        target_phone=original_target_phone,
                        expected_time_ms=expected_time,
                        duration_ms=duration_ms,
                        posterior=posterior,
                    ):
                        rejected_leading_noise = True
                        continue
                    label_bonus = 0.25 if candidate.role in preferred_labels else -0.05
                    decoded_bonus = 0.35 if "decoded_event" in candidate.warnings else 0.0
                    distance_penalty = abs(candidate.anchor_abs_ms - expected_time) / duration_ms
                    score = float(candidate.score) + label_bonus + decoded_bonus - (0.90 * distance_penalty)
                    if score > best_score:
                        best_score = score
                        best_idx = cand_idx
            if best_idx is not None:
                pass
        if best_idx is None:
            synthetic = _synthetic_anchor_from_expected(row, expected_time, posterior, role)
            if rejected_leading_noise:
                synthetic = replace(
                    synthetic,
                    warnings=tuple(
                        dict.fromkeys((*synthetic.warnings, "leading_sonorant_noise_candidate_rejected"))
                    ),
                )
            out.append(synthetic)
            last_time = synthetic.anchor_abs_ms
            continue
        if target_phone_index is None:
            used.add(best_idx)
        chosen = candidates[best_idx]
        span = estimate_vowel_span(posterior, chosen.anchor_abs_ms)
        warnings = _anchor_warnings_with_target(chosen, role, target_phone_index)
        if (
            target_phone_index is not None
            and last_target_phone_index is not None
            and target_phone_index < last_target_phone_index
        ):
            warnings.append("alias_target_backtrack")
        chosen = replace(
            chosen,
            role=role,
            vowel_start_abs_ms=span.get("vowel_start_abs_ms", chosen.vowel_start_abs_ms),
            vowel_end_abs_ms=span.get("vowel_end_abs_ms", chosen.vowel_end_abs_ms),
            warnings=tuple(dict.fromkeys(warnings)),
        )
        if out:
            prev = next((item for item in reversed(out) if item is not None), None)
            if prev is not None:
                chosen = replace(chosen, previous_vowel_end_abs_ms=prev.vowel_end_abs_ms)
        out.append(chosen)
        last_time = chosen.anchor_abs_ms
        last_target_phone_index = chosen.expected_phone_index
    out = _repair_korean_compound_vowel_skip_gap_anchors(
        out,
        template_rows,
        row_roles,
        alias_targets,
        expected_phones or (),
        language=language,
    )
    out = _repair_korean_sonorant_cv_skip_gap_anchors(
        out,
        template_rows,
        row_roles,
        alias_targets,
        expected_phones or (),
        language=language,
    )
    out = _repair_korean_interleaved_cvc_compressed_cv_anchors(
        out,
        template_rows,
        row_roles,
        alias_targets,
        expected_phones or (),
        language=language,
    )
    out = _repair_korean_interleaved_cvc_late_suffix_block_anchors(
        out,
        template_rows,
        row_roles,
        alias_targets,
        expected_phones or (),
        language=language,
    )
    out = _repair_korean_cv_skip_gap_anchors(
        out,
        template_rows,
        row_roles,
        alias_targets,
        expected_phones or (),
        language=language,
    )
    return _refine_anchor_sequence_locally(posterior, out, language=language)


def _is_likely_leading_sonorant_noise_anchor(
    candidate: OtoAnchor,
    *,
    target_phone_index: int | None,
    target_phone: str = "",
    expected_time_ms: float | None,
    duration_ms: float,
    posterior: FramePosterior,
) -> bool:
    if target_phone_index is None or int(target_phone_index) <= 0:
        return False
    if expected_time_ms is None or float(duration_ms) < 240.0:
        return False
    phone = str(candidate.expected_phone or target_phone or "").strip().lower()
    if not _phone_is_sonorant_like(phone):
        return False
    anchor_time = float(candidate.anchor_abs_ms)
    leading_edge_ms = max(30.0, min(85.0, float(duration_ms) * 0.035))
    if anchor_time > leading_edge_ms:
        return False
    expected_gap = float(expected_time_ms) - anchor_time
    if expected_gap < max(90.0, float(duration_ms) * 0.06):
        return False
    if float(candidate.boundary_confidence or 0.0) >= 0.50 and float(candidate.nucleus_confidence or 0.0) >= 0.35:
        return False

    silence = _acoustic_track_value_at(posterior, "silence_likelihood", anchor_time)
    voicing = _acoustic_track_value_at(posterior, "voicing", anchor_time)
    low_boundary = float(candidate.boundary_confidence or 0.0) < 0.30
    breath_like = silence is not None and silence >= 0.45
    weak_voice = voicing is not None and voicing <= 0.22
    return bool(low_boundary or breath_like or weak_voice)


def _repair_korean_interleaved_cvc_compressed_cv_anchors(
    anchors: Sequence[OtoAnchor | None],
    rows: Sequence[OtoTemplateRow],
    roles: Sequence[str],
    targets: Sequence[int | None],
    expected_phones: Sequence[str],
    *,
    language: str = "",
) -> list[OtoAnchor | None]:
    if not _is_korean_language_name(language):
        return list(anchors)
    expected = [str(phone or "").strip().lower() for phone in expected_phones]
    if len(anchors) < 5 or not expected:
        return list(anchors)

    repaired: list[OtoAnchor | None] = list(anchors)
    contextual_roles: list[str] = []
    target_ints: list[int | None] = []
    for row_idx, row in enumerate(rows):
        target = targets[row_idx] if row_idx < len(targets) else None
        base_role = roles[row_idx] if row_idx < len(roles) else _alias_type_for_row(row.alias, "auto")
        contextual_roles.append(
            _contextual_alias_role_for_row_sequence(
                rows,
                roles,
                row_idx,
                expected,
                target,
                base_role=base_role,
                language=language,
            )
        )
        target_ints.append(int(target) if target is not None else None)

    for row_idx in range(1, len(repaired) - 1):
        prev_anchor = repaired[row_idx - 1]
        anchor = repaired[row_idx]
        next_anchor = repaired[row_idx + 1]
        if prev_anchor is None or anchor is None or next_anchor is None:
            continue
        if str(contextual_roles[row_idx - 1]).strip().lower() != "vc":
            continue
        if str(contextual_roles[row_idx]).strip().lower() != "cv":
            continue
        if str(contextual_roles[row_idx + 1]).strip().lower() != "vc":
            continue
        if str(rows[row_idx - 1].wav) != str(rows[row_idx].wav) or str(rows[row_idx].wav) != str(rows[row_idx + 1].wav):
            continue
        prev_target = target_ints[row_idx - 1]
        target = target_ints[row_idx]
        next_target = target_ints[row_idx + 1]
        if prev_target is None or target is None or next_target is None:
            continue
        if not (prev_target < target < next_target):
            continue
        phones = _alias_phone_sequence(rows[row_idx].alias)
        onset = str(phones[0]).strip().lower() if phones else ""
        if _phone_is_sonorant_like(onset):
            continue
        prev_gap = float(anchor.anchor_abs_ms) - float(prev_anchor.anchor_abs_ms)
        next_gap = float(next_anchor.anchor_abs_ms) - float(anchor.anchor_abs_ms)
        if prev_gap < 420.0 or next_gap > 120.0:
            continue
        new_gap = 180.0
        new_time = float(prev_anchor.anchor_abs_ms) + new_gap
        move = new_time - float(anchor.anchor_abs_ms)
        if move > -180.0 or move < -460.0:
            continue
        if float(next_anchor.anchor_abs_ms) - new_time < 180.0:
            continue
        old_time = float(anchor.anchor_abs_ms)
        warnings = (
            *anchor.warnings,
            f"korean_interleaved_cvc_compressed_cv_repaired:{old_time:.1f}->{new_time:.1f}",
        )
        repaired[row_idx] = replace(
            anchor,
            anchor_abs_ms=new_time,
            refined_from_abs_ms=anchor.refined_from_abs_ms if anchor.refined_from_abs_ms is not None else old_time,
            local_refine_delta_ms=(anchor.local_refine_delta_ms or 0.0) + move,
            warnings=tuple(dict.fromkeys(warnings)),
        )
    return repaired


def _repair_korean_interleaved_cvc_late_suffix_block_anchors(
    anchors: Sequence[OtoAnchor | None],
    rows: Sequence[OtoTemplateRow],
    roles: Sequence[str],
    targets: Sequence[int | None],
    expected_phones: Sequence[str],
    *,
    language: str = "",
) -> list[OtoAnchor | None]:
    if not _is_korean_language_name(language):
        return list(anchors)
    expected = [str(phone or "").strip().lower() for phone in expected_phones]
    if len(anchors) < 7 or not expected:
        return list(anchors)

    repaired: list[OtoAnchor | None] = list(anchors)
    contextual_roles: list[str] = []
    target_ints: list[int | None] = []
    for row_idx, row in enumerate(rows):
        target = targets[row_idx] if row_idx < len(targets) else None
        base_role = roles[row_idx] if row_idx < len(roles) else _alias_type_for_row(row.alias, "auto")
        contextual_roles.append(
            _contextual_alias_role_for_row_sequence(
                rows,
                roles,
                row_idx,
                expected,
                target,
                base_role=base_role,
                language=language,
            )
        )
        target_ints.append(int(target) if target is not None else None)

    for row_idx in range(1, len(repaired) - 2):
        prev_anchor = repaired[row_idx - 1]
        anchor = repaired[row_idx]
        if prev_anchor is None or anchor is None:
            continue
        if str(contextual_roles[row_idx - 1]).strip().lower() != "vc":
            continue
        if str(contextual_roles[row_idx]).strip().lower() != "cv":
            continue
        if str(rows[row_idx - 1].wav) != str(rows[row_idx].wav):
            continue
        prev_target = target_ints[row_idx - 1]
        target = target_ints[row_idx]
        if prev_target is None or target is None or not (prev_target < target):
            continue
        phones = _alias_phone_sequence(rows[row_idx].alias)
        onset = str(phones[0]).strip().lower() if phones else ""
        if _phone_is_sonorant_like(onset):
            continue

        block_end = row_idx
        last_target = target
        while block_end + 1 < len(repaired) and str(rows[block_end + 1].wav) == str(rows[row_idx].wav):
            next_anchor = repaired[block_end + 1]
            next_target = target_ints[block_end + 1]
            if next_anchor is None or next_target is None or next_target <= last_target:
                break
            block_end += 1
            last_target = next_target
        block_len = block_end - row_idx + 1
        if block_len < 4 or block_len > 6:
            continue
        if any(repaired[idx] is None for idx in range(row_idx, block_end + 1)):
            continue

        prev_gap = float(anchor.anchor_abs_ms) - float(prev_anchor.anchor_abs_ms)
        if prev_gap < 470.0:
            continue
        suffix_times = [float(repaired[idx].anchor_abs_ms) for idx in range(row_idx, block_end + 1) if repaired[idx] is not None]
        suffix_gaps = [right - left for left, right in zip(suffix_times[:-1], suffix_times[1:])]
        if not suffix_gaps or min(suffix_gaps) > 90.0:
            continue
        new_time = float(prev_anchor.anchor_abs_ms) + 180.0
        move = new_time - float(anchor.anchor_abs_ms)
        if move > -220.0 or move < -420.0:
            continue
        if new_time - float(prev_anchor.anchor_abs_ms) < 140.0:
            continue

        for shift_idx in range(row_idx, block_end + 1):
            item = repaired[shift_idx]
            if item is None:
                continue
            old_time = float(item.anchor_abs_ms)
            shifted_time = old_time + move
            if shift_idx == row_idx:
                shifted_time = new_time
            if shift_idx > row_idx:
                previous_item = repaired[shift_idx - 1]
                if previous_item is not None and shifted_time - float(previous_item.anchor_abs_ms) < 25.0:
                    shifted_time = float(previous_item.anchor_abs_ms) + 25.0
            warnings = (
                *item.warnings,
                f"korean_interleaved_cvc_late_suffix_block_repaired:{old_time:.1f}->{shifted_time:.1f}",
            )
            repaired[shift_idx] = replace(
                item,
                anchor_abs_ms=shifted_time,
                refined_from_abs_ms=item.refined_from_abs_ms if item.refined_from_abs_ms is not None else old_time,
                local_refine_delta_ms=(item.local_refine_delta_ms or 0.0) + (shifted_time - old_time),
                warnings=tuple(dict.fromkeys(warnings)),
            )
    return repaired


def _repair_korean_sonorant_cv_skip_gap_anchors(
    anchors: Sequence[OtoAnchor | None],
    rows: Sequence[OtoTemplateRow],
    roles: Sequence[str],
    targets: Sequence[int | None],
    expected_phones: Sequence[str],
    *,
    language: str = "",
) -> list[OtoAnchor | None]:
    if not _is_korean_language_name(language):
        return list(anchors)
    expected = [str(phone or "").strip().lower() for phone in expected_phones]
    if len(anchors) < 5 or not expected:
        return list(anchors)

    repaired: list[OtoAnchor | None] = list(anchors)
    group: list[int] = []
    last_wav = ""
    last_target: int | None = None

    def flush() -> None:
        nonlocal group
        if len(group) >= 5 and all(repaired[row_idx] is not None for row_idx in group):
            times = [float(repaired[row_idx].anchor_abs_ms) for row_idx in group if repaired[row_idx] is not None]
            gaps = [right - left for left, right in zip(times[:-1], times[1:])]
            _repair_korean_cv_leading_skip_gap_group(repaired, rows, group, times, gaps)
        group = []

    for row_idx, anchor in enumerate(repaired):
        target = targets[row_idx] if row_idx < len(targets) else None
        wav = str(rows[row_idx].wav if row_idx < len(rows) else "")
        if wav != last_wav:
            flush()
            last_wav = wav
            last_target = None
        base_role = roles[row_idx] if row_idx < len(roles) else _alias_type_for_row(rows[row_idx].alias, "auto")
        role = _contextual_alias_role_for_row_sequence(
            rows,
            roles,
            row_idx,
            expected,
            target,
            base_role=base_role,
            language=language,
        )
        target_int = int(target) if target is not None else None
        phones = _alias_phone_sequence(rows[row_idx].alias if row_idx < len(rows) else "")
        onset = str(phones[0]).strip().lower() if phones else ""
        if target_int is not None and last_target is not None and target_int < last_target:
            flush()
            last_target = None
        is_sonorant_cv = (
            anchor is not None
            and target_int is not None
            and str(role or "").strip().lower() == "cv"
            and _phone_is_sonorant_like(onset)
            and (last_target is None or target_int > last_target)
        )
        if not is_sonorant_cv:
            continue
        group.append(row_idx)
        last_target = target_int
    flush()
    return repaired


def _repair_korean_cv_skip_gap_anchors(
    anchors: Sequence[OtoAnchor | None],
    rows: Sequence[OtoTemplateRow],
    roles: Sequence[str],
    targets: Sequence[int | None],
    expected_phones: Sequence[str],
    *,
    language: str = "",
) -> list[OtoAnchor | None]:
    if not _is_korean_language_name(language):
        return list(anchors)
    expected = [str(phone or "").strip().lower() for phone in expected_phones]
    if len(anchors) < 5 or not expected:
        return list(anchors)

    repaired: list[OtoAnchor | None] = list(anchors)
    group: list[int] = []
    last_target: int | None = None

    def flush() -> None:
        nonlocal group
        if len(group) >= 5:
            _repair_korean_cv_skip_gap_group(repaired, rows, group)
        group = []

    for row_idx, anchor in enumerate(repaired):
        target = targets[row_idx] if row_idx < len(targets) else None
        base_role = roles[row_idx] if row_idx < len(roles) else _alias_type_for_row(rows[row_idx].alias, "auto")
        role = _contextual_alias_role_for_row_sequence(
            rows,
            roles,
            row_idx,
            expected,
            target,
            base_role=base_role,
            language=language,
        )
        target_int = int(target) if target is not None else None
        is_ordered_cv = (
            anchor is not None
            and target_int is not None
            and str(role or "").strip().lower() == "cv"
            and (last_target is None or target_int > last_target)
        )
        if not is_ordered_cv:
            flush()
            last_target = None
            continue
        group.append(row_idx)
        last_target = target_int
    flush()
    return repaired


def _repair_korean_compound_vowel_skip_gap_anchors(
    anchors: Sequence[OtoAnchor | None],
    rows: Sequence[OtoTemplateRow],
    roles: Sequence[str],
    targets: Sequence[int | None],
    expected_phones: Sequence[str],
    *,
    language: str = "",
) -> list[OtoAnchor | None]:
    if not _is_korean_language_name(language):
        return list(anchors)
    expected = [str(phone or "").strip().lower() for phone in expected_phones]
    if len(anchors) < 4 or not expected:
        return list(anchors)

    repaired: list[OtoAnchor | None] = list(anchors)
    group: list[int] = []
    last_target: int | None = None

    def flush() -> None:
        nonlocal group
        if len(group) >= 4:
            _repair_korean_compound_vowel_skip_gap_group(repaired, rows, group)
        group = []

    for row_idx, anchor in enumerate(repaired):
        target = targets[row_idx] if row_idx < len(targets) else None
        base_role = roles[row_idx] if row_idx < len(roles) else _alias_type_for_row(rows[row_idx].alias, "auto")
        role = _contextual_alias_role_for_row_sequence(
            rows,
            roles,
            row_idx,
            expected,
            target,
            base_role=base_role,
            language=language,
        )
        target_int = int(target) if target is not None else None
        phones = _alias_phone_sequence(rows[row_idx].alias if row_idx < len(rows) else "")
        is_compound_vowel_cv = (
            anchor is not None
            and target_int is not None
            and str(role or "").strip().lower() == "cv"
            and len(phones) == 1
            and str(phones[0]).strip().lower() in _KOREAN_COMPACT_GLIDE_VOWEL_PHONES
            and (last_target is None or target_int > last_target)
        )
        if not is_compound_vowel_cv:
            flush()
            last_target = None
            continue
        group.append(row_idx)
        last_target = target_int
    flush()
    return repaired


def _repair_korean_compound_vowel_skip_gap_group(
    anchors: list[OtoAnchor | None],
    rows: Sequence[OtoTemplateRow],
    group: Sequence[int],
) -> None:
    times: list[float] = []
    for row_idx in group:
        anchor = anchors[row_idx]
        if anchor is None:
            return
        times.append(float(anchor.anchor_abs_ms))
    if len(times) < 4:
        return
    gaps = [right - left for left, right in zip(times[:-1], times[1:])]
    if any(not np.isfinite(gap) or gap <= 0.0 for gap in gaps):
        return
    max_gap_index = int(np.argmax(np.asarray(gaps, dtype=np.float32)))
    if max_gap_index < 1:
        return
    max_gap = float(gaps[max_gap_index])
    cadence = float(gaps[max_gap_index - 1])
    if cadence < 320.0 or cadence > 620.0:
        return
    if max_gap < max(820.0, cadence * 1.85):
        return
    if len(group) - (max_gap_index + 1) < 2:
        return

    for pos in range(max_gap_index + 1, len(group)):
        row_idx = group[pos]
        anchor = anchors[row_idx]
        prev_anchor = anchors[group[pos - 1]]
        if anchor is None or prev_anchor is None:
            continue
        old_time = float(anchor.anchor_abs_ms)
        new_time = float(prev_anchor.anchor_abs_ms) + cadence
        if old_time - new_time < 160.0 or old_time - new_time > 720.0:
            continue
        warnings = (
            *anchor.warnings,
            f"korean_compound_vowel_skip_gap_repaired:{old_time:.1f}->{new_time:.1f}",
        )
        anchors[row_idx] = replace(
            anchor,
            anchor_abs_ms=new_time,
            refined_from_abs_ms=anchor.refined_from_abs_ms if anchor.refined_from_abs_ms is not None else old_time,
            local_refine_delta_ms=(anchor.local_refine_delta_ms or 0.0) + (new_time - old_time),
            warnings=tuple(dict.fromkeys(warnings)),
        )


def _repair_korean_cv_skip_gap_group(
    anchors: list[OtoAnchor | None],
    rows: Sequence[OtoTemplateRow],
    group: Sequence[int],
) -> None:
    times: list[float] = []
    for row_idx in group:
        anchor = anchors[row_idx]
        if anchor is None:
            return
        times.append(float(anchor.anchor_abs_ms))
    if len(times) < 5:
        return
    gaps = [right - left for left, right in zip(times[:-1], times[1:])]
    if any(not np.isfinite(gap) or gap <= 0.0 for gap in gaps):
        return
    max_gap_index = int(np.argmax(np.asarray(gaps, dtype=np.float32)))
    if max_gap_index < 1:
        _repair_korean_cv_leading_skip_gap_group(anchors, rows, group, times, gaps)
        return
    if len(group) - (max_gap_index + 1) < 2:
        return
    normal_gaps = [gap for idx, gap in enumerate(gaps) if idx != max_gap_index and 250.0 <= gap <= 760.0]
    if len(normal_gaps) < 3:
        return
    period = float(np.median(np.asarray(normal_gaps, dtype=np.float32)))
    max_gap = float(gaps[max_gap_index])
    if period < 360.0 or period > 620.0:
        return
    if max_gap < max(820.0, period * 1.72):
        return
    shift = max_gap - period
    if shift < 300.0 or shift > 620.0:
        return
    shift = max(300.0, min(560.0, shift))
    first_shifted = max_gap_index + 1
    min_allowed = times[max_gap_index] + max(190.0, period * 0.55)
    if times[first_shifted] - shift < min_allowed:
        return

    for pos in range(first_shifted, len(group)):
        row_idx = group[pos]
        anchor = anchors[row_idx]
        if anchor is None:
            continue
        old_time = float(anchor.anchor_abs_ms)
        new_time = max(0.0, old_time - shift)
        warnings = (
            *anchor.warnings,
            f"korean_cv_skip_gap_repaired:{old_time:.1f}->{new_time:.1f}",
        )
        anchors[row_idx] = replace(
            anchor,
            anchor_abs_ms=new_time,
            refined_from_abs_ms=anchor.refined_from_abs_ms if anchor.refined_from_abs_ms is not None else old_time,
            local_refine_delta_ms=(anchor.local_refine_delta_ms or 0.0) - shift,
            warnings=tuple(dict.fromkeys(warnings)),
        )


def _repair_korean_cv_leading_skip_gap_group(
    anchors: list[OtoAnchor | None],
    rows: Sequence[OtoTemplateRow],
    group: Sequence[int],
    times: Sequence[float],
    gaps: Sequence[float],
) -> None:
    if len(group) < 5 or len(gaps) < 4:
        return
    first_row_idx = int(group[0])
    if first_row_idx >= len(rows):
        return
    phones = _alias_phone_sequence(rows[first_row_idx].alias)
    onset = str(phones[0]).strip().lower() if phones else ""
    if not _phone_is_sonorant_like(onset):
        return
    first_gap = float(gaps[0])
    later_gaps = [float(gap) for gap in gaps[1:] if 280.0 <= float(gap) <= 680.0]
    if len(later_gaps) < 3:
        return
    cadence = float(np.median(np.asarray(later_gaps, dtype=np.float32)))
    if cadence < 360.0 or cadence > 620.0:
        return
    if first_gap < max(820.0, cadence * 1.65):
        return
    anchor = anchors[first_row_idx]
    if anchor is None:
        return
    old_time = float(anchor.anchor_abs_ms)
    new_time = max(0.0, float(times[1]) - cadence)
    move = new_time - old_time
    if move < 180.0 or move > 620.0:
        return
    if new_time + 1e-5 >= float(times[1]) - 120.0:
        return
    warnings = (
        *anchor.warnings,
        f"korean_cv_leading_skip_gap_repaired:{old_time:.1f}->{new_time:.1f}",
    )
    anchors[first_row_idx] = replace(
        anchor,
        anchor_abs_ms=new_time,
        refined_from_abs_ms=anchor.refined_from_abs_ms if anchor.refined_from_abs_ms is not None else old_time,
        local_refine_delta_ms=(anchor.local_refine_delta_ms or 0.0) + move,
        warnings=tuple(dict.fromkeys(warnings)),
    )


def _acoustic_track_value_at(posterior: FramePosterior, name: str, time_ms: float) -> float | None:
    times = np.asarray(posterior.times_ms, dtype=np.float32)
    values = np.asarray(posterior.acoustic_scores.get(name, []), dtype=np.float32)
    if times.size == 0 or values.shape[0] != times.shape[0]:
        return None
    idx = _window_idx(times, float(time_ms))
    return float(np.clip(values[idx], 0.0, 1.0))


def expected_slots_for_template_rows(
    template_rows: Sequence[OtoTemplateRow],
    expected_phones: Sequence[str],
    *,
    language: str = "",
) -> list[ExpectedSlot]:
    expected = [str(phone or "").strip().lower() for phone in expected_phones]
    if not template_rows or not expected:
        return []
    targets = _alias_targets_from_template_rows_or_dp(template_rows, expected, language=language)
    out: list[ExpectedSlot] = []
    seen: set[tuple[int, str]] = set()
    roles = [_alias_type_for_row(row.alias, "auto") for row in template_rows]
    for row_idx, (row, target_index) in enumerate(zip(template_rows, targets)):
        if target_index is None or target_index < 0 or target_index >= len(expected):
            continue
        if _is_terminal_silence_alias(row.alias):
            continue
        base_role = roles[row_idx] if row_idx < len(roles) else _alias_type_for_row(row.alias, "auto")
        role = _contextual_alias_role_for_row_sequence(
            template_rows,
            roles,
            row_idx,
            expected,
            int(target_index),
            base_role=base_role,
            language=language,
        )
        event_label = _slot_event_label_for_alias_role(role)
        if role == "vv" and target_index > 0 and not is_vowel_phone(expected[int(target_index) - 1], language):
            event_label = "cv_boundary"
        if role == "cv_head" and (
            not is_vowel_phone(expected[target_index], language)
            or _cv_head_phones_are_consonant_like(_alias_phone_sequence(row.alias))
        ):
            event_label = "phone_change"
        _append_expected_slot(
            out,
            seen,
            phone_index=int(target_index),
            phone=expected[target_index],
            role=role,
            event_label=event_label,
        )
        if role == "vc":
            next_vowel_index = _next_vowel_index(expected, int(target_index), language=language)
            if next_vowel_index is not None:
                _append_expected_slot(
                    out,
                    seen,
                    phone_index=int(next_vowel_index),
                    phone=expected[next_vowel_index],
                    role="implicit_cv",
                    event_label="cv_boundary",
                )
    return out


def timeline_expected_slots_for_template_rows(
    template_rows: Sequence[OtoTemplateRow],
    expected_phones: Sequence[str],
    *,
    language: str = "",
) -> list[ExpectedSlot]:
    slots = expected_slots_for_template_rows(template_rows, expected_phones, language=language)
    if _is_korean_language_name(language):
        slots = _prepend_korean_leading_context_slots(
            template_rows,
            expected_phones,
            slots,
            language=language,
        )
    if _is_japanese_language_name(language) and _ja_cvvc_leading_context_slots_enabled():
        slots = _prepend_japanese_cvvc_leading_context_slots(
            template_rows,
            expected_phones,
            slots,
            language=language,
        )
    if len(slots) <= 1:
        return slots
    event_order = {"phone_change": 0, "cv_boundary": 1, "vowel_nucleus": 2}
    ordered = sorted(
        slots,
        key=lambda slot: (
            int(slot.phone_index),
            int(event_order.get(str(slot.event_label), 9)),
            int(slot.slot_index),
        ),
    )
    return [
        ExpectedSlot(
            slot_index=idx,
            phone_index=int(slot.phone_index),
            phone=str(slot.phone),
            role=str(slot.role),
            event_label=str(slot.event_label),
        )
        for idx, slot in enumerate(ordered)
    ]


def _prepend_korean_leading_context_slots(
    template_rows: Sequence[OtoTemplateRow],
    expected_phones: Sequence[str],
    row_slots: Sequence[ExpectedSlot],
    *,
    language: str,
) -> list[ExpectedSlot]:
    if not template_rows or not row_slots:
        return list(row_slots)
    expected = [str(phone or "").strip().lower() for phone in expected_phones]
    if not expected:
        return list(row_slots)
    roles = [_alias_type_for_row(row.alias, "auto") for row in template_rows]
    targets = _alias_targets_from_template_rows_or_dp(template_rows, expected, language=language)
    first_start: int | None = None
    for row, role, target in zip(template_rows, roles, targets):
        if target is None:
            continue
        if str(role or "").strip().lower() == "vc":
            return list(row_slots)
        start = _alias_represented_start_index(
            row.alias,
            role,
            expected,
            int(target),
            language=language,
        )
        first_start = max(0, min(int(start), len(expected)))
        break
    if first_start is None or first_start <= 0:
        return list(row_slots)

    context_slots = _korean_leading_context_slots(expected, first_start)
    if not context_slots:
        return list(row_slots)
    return [*context_slots, *row_slots]


def _prepend_japanese_cvvc_leading_context_slots(
    template_rows: Sequence[OtoTemplateRow],
    expected_phones: Sequence[str],
    row_slots: Sequence[ExpectedSlot],
    *,
    language: str,
) -> list[ExpectedSlot]:
    if not template_rows or not row_slots:
        return list(row_slots)
    expected = [str(phone or "").strip().lower() for phone in expected_phones]
    if not expected:
        return list(row_slots)
    roles = [_alias_type_for_row(row.alias, "auto") for row in template_rows]
    targets = _alias_targets_from_template_rows_or_dp(template_rows, expected, language=language)
    first_start: int | None = None
    for row, role, target in zip(template_rows, roles, targets):
        if target is None:
            continue
        alias = str(row.alias or "").strip()
        if not alias or _is_terminal_silence_alias(alias) or _is_nonphonetic_special_alias(alias):
            continue
        first_start = _alias_represented_start_index(
            alias,
            role,
            expected,
            int(target),
            language=language,
        )
        break
    if first_start is None or first_start <= 0:
        return list(row_slots)

    context_slots = _japanese_leading_cv_context_slots(expected, first_start, row_slots)
    if not context_slots:
        return list(row_slots)
    return [*context_slots, *row_slots]


def _japanese_leading_cv_context_slots(
    expected: Sequence[str],
    first_represented_start: int,
    row_slots: Sequence[ExpectedSlot],
) -> list[ExpectedSlot]:
    out: list[ExpectedSlot] = []
    seen = {(int(slot.phone_index), str(slot.event_label)) for slot in row_slots}
    limit = max(0, min(int(first_represented_start), len(expected) - 1))
    for phone_index in range(0, limit + 1):
        phone = str(expected[phone_index] or "").strip().lower()
        if not phone or not is_vowel_phone(phone, "japanese"):
            continue
        if phone_index <= 0 or is_vowel_phone(expected[phone_index - 1], "japanese"):
            continue
        key = (phone_index, "cv_boundary")
        if key in seen:
            continue
        seen.add(key)
        out.append(
            ExpectedSlot(
                slot_index=len(out),
                phone_index=phone_index,
                phone=phone,
                role="implicit_cv",
                event_label="cv_boundary",
            )
        )
    return out


def _korean_leading_context_slots(expected: Sequence[str], stop_index: int) -> list[ExpectedSlot]:
    out: list[ExpectedSlot] = []
    seen: set[tuple[int, str]] = set()
    seen_vowel = False
    limit = max(0, min(int(stop_index), len(expected)))
    for phone_index in range(limit):
        phone = str(expected[phone_index] or "").strip().lower()
        if not phone:
            continue
        if is_vowel_phone(phone, "korean"):
            seen_vowel = True
            _append_expected_slot(
                out,
                seen,
                phone_index=phone_index,
                phone=phone,
                role="v",
                event_label="vowel_nucleus",
            )
            continue
        if not seen_vowel:
            continue
        _append_expected_slot(
            out,
            seen,
            phone_index=phone_index,
            phone=phone,
            role="vc",
            event_label="phone_change",
        )
    return out


def _append_expected_slot(
    out: list[ExpectedSlot],
    seen: set[tuple[int, str]],
    *,
    phone_index: int,
    phone: str,
    role: str,
    event_label: str,
) -> None:
    key = (phone_index, event_label)
    if key in seen:
        return
    seen.add(key)
    out.append(
        ExpectedSlot(
            slot_index=len(out),
            phone_index=phone_index,
            phone=phone,
            role=role,
            event_label=event_label,
        )
    )


def _is_terminal_silence_alias(alias: str) -> bool:
    parts = [part.strip().lower() for part in str(alias or "").split() if part.strip()]
    return len(parts) >= 2 and _is_terminal_silence_token(parts[-1])


def _is_terminal_silence_token(token: str) -> bool:
    normalized = str(token or "").strip().lower()
    return normalized == "-" or bool(re.fullmatch(r"-\d{1,3}", normalized))


def _is_nonphonetic_special_alias(alias: str) -> bool:
    raw = str(alias or "").strip()
    normalized = raw.lower()
    if not normalized:
        return True
    if _is_hold_release_suffix_alias(raw):
        return True
    compact = "".join(part for part in normalized.split())
    stripped_compact = "".join(
        _strip_alias_attached_pitch_suffix_token_preserve_case(part).strip().lower()
        for part in raw.split()
        if part.strip()
    )
    if len(raw.split()) == 1 and _is_breath_alias_with_attached_pitch_style_suffix_token(raw):
        return True
    if compact.startswith("br") and compact[2:].isdigit():
        return True
    if stripped_compact == "br" or (stripped_compact.startswith("br") and stripped_compact[2:].isdigit()):
        return True
    if any(char in normalized for char in {"・", "･"}):
        return True
    return any(char in normalized for char in {"息", "吸"})


def _is_hold_release_suffix_alias(alias: str) -> bool:
    raw = str(alias or "").strip()
    if not raw:
        return False
    parts = [part for part in raw.split() if part]
    if len(parts) == 2 and parts[1] in {"H", "L"} and _alias_phones(parts[0]):
        return True
    if len(parts) == 1 and len(parts[0]) >= 2 and parts[0][-1] in {"H", "L"}:
        stem = parts[0][:-1].strip("_- ")
        if stem and _alias_phones(stem):
            return True
    return False


def estimate_vowel_span(posterior: FramePosterior, anchor_abs_ms: float, *, threshold: float = 0.35) -> dict:
    times = np.asarray(posterior.times_ms, dtype=np.float32)
    vowel = np.asarray(posterior.class_probs.get("vowel", []), dtype=np.float32)
    if times.size == 0 or vowel.shape[0] != times.shape[0]:
        return {}
    start_idx = int(np.searchsorted(times, anchor_abs_ms, side="left"))
    start_idx = max(0, min(start_idx, times.shape[0] - 1))
    while start_idx > 0 and float(vowel[start_idx - 1]) >= threshold:
        start_idx -= 1
    end_idx = int(np.searchsorted(times, anchor_abs_ms, side="left"))
    end_idx = max(0, min(end_idx, times.shape[0] - 1))
    while end_idx + 1 < times.shape[0] and float(vowel[end_idx + 1]) >= threshold:
        end_idx += 1
    return {
        "vowel_start_abs_ms": float(times[start_idx]),
        "vowel_end_abs_ms": float(times[end_idx]),
    }


def estimate_vowel_nucleus(
    posterior: FramePosterior,
    anchor_abs_ms: float,
    *,
    vowel_start_abs_ms: float | None = None,
    vowel_end_abs_ms: float | None = None,
) -> tuple[float | None, float, tuple[str, ...]]:
    times = np.asarray(posterior.times_ms, dtype=np.float32)
    if times.size == 0:
        return None, 0.0, ("empty_posterior",)
    vowel = np.asarray(posterior.class_probs.get("vowel", []), dtype=np.float32)
    if vowel.shape[0] != times.shape[0]:
        vowel = np.zeros_like(times)
    rms_track = _normalized_track(posterior, "rms", times)
    voicing_track = _normalized_track(posterior, "voicing", times)
    centroid = _normalized_track(posterior, "spectral_centroid", times)
    formant_stability = 1.0 - np.clip(np.abs(np.gradient(centroid.astype(np.float32))), 0.0, 1.0)

    if vowel_start_abs_ms is None or vowel_end_abs_ms is None:
        span = estimate_vowel_span(posterior, anchor_abs_ms)
        vowel_start_abs_ms = span.get("vowel_start_abs_ms")
        vowel_end_abs_ms = span.get("vowel_end_abs_ms")
    if vowel_start_abs_ms is None or vowel_end_abs_ms is None:
        center_idx = int(np.searchsorted(times, anchor_abs_ms, side="left"))
        center_idx = max(0, min(center_idx, times.shape[0] - 1))
        start_idx = max(0, center_idx - 3)
        end_idx = min(times.shape[0] - 1, center_idx + 3)
    else:
        start_idx = int(np.searchsorted(times, float(vowel_start_abs_ms), side="left"))
        end_idx = int(np.searchsorted(times, float(vowel_end_abs_ms), side="right")) - 1
        start_idx = max(0, min(start_idx, times.shape[0] - 1))
        end_idx = max(start_idx, min(end_idx, times.shape[0] - 1))

    if end_idx <= start_idx:
        return float(times[start_idx]), 0.0, ("nucleus_span_too_short",)

    idx_slice = slice(start_idx, end_idx + 1)
    local_vowel = np.clip(vowel[idx_slice], 0.0, 1.0)
    local_energy = np.clip(rms_track[idx_slice], 0.0, 1.0)
    local_voicing = np.clip(voicing_track[idx_slice], 0.0, 1.0)
    local_formant = np.clip(formant_stability[idx_slice], 0.0, 1.0)
    continuity = np.minimum(local_voicing, _left_context_max(local_voicing, frames=2))
    score = np.clip(
        0.34 * local_vowel + 0.30 * local_energy + 0.22 * local_formant + 0.14 * continuity,
        0.0,
        1.0,
    )
    local_idx = int(np.argmax(score))
    global_idx = int(start_idx + local_idx)
    warnings: list[str] = []
    conf = float(score[local_idx])
    if conf < 0.35:
        warnings.append(f"low_vowel_nucleus_confidence:{conf:.3f}")
    if float(local_voicing[local_idx]) < 0.25:
        warnings.append("weak_voicing_nucleus")
    if float(local_formant[local_idx]) < 0.20:
        warnings.append("unstable_formant_nucleus")
    return float(times[global_idx]), conf, tuple(warnings)


def _anchor_boundary_confidence(
    posterior: FramePosterior,
    anchor_abs_ms: float,
    *,
    role: str,
) -> float:
    times = np.asarray(posterior.times_ms, dtype=np.float32)
    if times.size == 0:
        return 0.0
    idx = _window_idx(times, anchor_abs_ms)
    vowel = _normalized_track(posterior, "vowel", times, source="class")
    consonant = _normalized_track(posterior, "consonant", times, source="class")
    transition = _normalized_track(posterior, "transition_likelihood", times)
    voicing = _normalized_track(posterior, "voicing", times)
    if role == "vowel_nucleus":
        return float(np.clip((0.55 * voicing[idx]) + (0.45 * vowel[idx]), 0.0, 1.0))
    left_cons = float(np.max(consonant[max(0, idx - 3) : idx + 1])) if idx >= 0 else 0.0
    return float(np.clip((0.42 * transition[idx]) + (0.33 * vowel[idx]) + (0.25 * left_cons), 0.0, 1.0))


def format_oto_line(wav: str, alias: str, timing: OtoTiming) -> str:
    return (
        f"{wav}={alias},"
        f"{timing.offset:.3f},{timing.consonant:.3f},{timing.cutoff:.3f},"
        f"{timing.preutterance:.3f},{timing.overlap:.3f}"
    )


def timing_to_dict(timing: OtoTiming) -> dict:
    return {
        "offset": timing.offset,
        "consonant": timing.consonant,
        "cutoff": timing.cutoff,
        "preutterance": timing.preutterance,
        "overlap": timing.overlap,
    }


def absolute_oto_positions(timing: OtoTiming) -> dict:
    return {
        "offset_abs": timing.offset,
        "overlap_abs": timing.offset + timing.overlap,
        "preutterance_abs": timing.offset + timing.preutterance,
        "consonant_abs": timing.offset + timing.consonant,
        "cutoff_abs": timing.offset + abs(timing.cutoff),
    }


def _oto_row_preutterance_abs(row: AdaptedOtoRow) -> float:
    return float(row.timing.offset) + float(row.timing.preutterance)


def repair_cvvc_vc_row_sequence(
    rows: Sequence[AdaptedOtoRow],
    config: OtoAdapterConfig | None = None,
) -> list[AdaptedOtoRow]:
    cfg = config or OtoAdapterConfig()
    if not _is_japanese_cvvc_config(cfg):
        return list(rows)
    out = list(rows)
    for index, row in enumerate(out):
        previous = out[index - 1] if index > 0 else None
        out[index] = _repair_cvvc_vc_row_from_previous(previous, row, cfg)
    return out


def _ja_cvvc_reference_derived_repairs_enabled() -> bool:
    raw = str(os.environ.get("UTOA_ENABLE_JA_CVVC_REFERENCE_REPAIRS", "") or "").strip().lower()
    return raw in {"1", "true", "yes", "on", "y"}


@dataclass(frozen=True)
class JaCvvcRepairDispatch:
    underscore_wav: bool = False
    unprefixed_wav: bool = False
    has_attached_pitch_suffix: bool = False
    has_separated_soft_suffix: bool = False
    has_yoon_cv: bool = False
    starts_with_vc_block: bool = False
    has_tail_moraic_n_glide_vc: bool = False
    unprefixed_obstruent_head: bool = False
    has_unprefixed_pitch_suffix: bool = False
    has_unprefixed_pitch_yoon_first_gap: bool = False
    has_headless_pitch_suffix: bool = False
    has_headless_soft_yoon_only: bool = False


def _ja_cvvc_repair_dispatch(
    rows: Sequence[AdaptedOtoRow],
    config: OtoAdapterConfig,
) -> JaCvvcRepairDispatch:
    underscore_wav = False
    unprefixed_wav = False
    has_attached_pitch_suffix = False
    has_separated_soft_suffix = False
    has_yoon_cv = False
    starts_with_vc_block = False
    has_tail_moraic_n_glide_vc = False
    unprefixed_obstruent_head = False
    has_unprefixed_pitch_suffix = False
    has_unprefixed_pitch_yoon_first_gap = False
    has_headless_pitch_suffix = False
    has_headless_soft_yoon_only = False

    segment_start = 0
    row_list = list(rows)
    while segment_start < len(row_list):
        wav_key = str(row_list[segment_start].wav or "").strip().lower()
        segment_end = segment_start + 1
        while (
            segment_end < len(row_list)
            and str(row_list[segment_end].wav or "").strip().lower() == wav_key
        ):
            segment_end += 1
        segment = row_list[segment_start:segment_end]
        wav = str(segment[0].wav or "").strip() if segment else ""
        wav_name = Path(wav).name
        segment_underscore = bool(wav_name) and wav_name.startswith("_")
        segment_unprefixed = bool(wav_name) and not segment_underscore
        roles = [_alias_type_for_row(row.alias, config.alias_type) for row in segment]
        aliases = [str(row.alias or "") for row in segment]
        segment_attached_pitch = any(_alias_has_attached_pitch_suffix(alias) for alias in aliases)
        segment_soft_suffix = any(_alias_has_separated_soft_suffix(alias) for alias in aliases)
        segment_yoon_cv = any(_is_yoon_cv_alias(alias) for alias in aliases)
        initial_vc_count = 0
        for role in roles:
            if role != "vc":
                break
            initial_vc_count += 1

        underscore_wav = underscore_wav or segment_underscore
        unprefixed_wav = unprefixed_wav or segment_unprefixed
        has_attached_pitch_suffix = has_attached_pitch_suffix or segment_attached_pitch
        has_separated_soft_suffix = has_separated_soft_suffix or segment_soft_suffix
        has_yoon_cv = has_yoon_cv or segment_yoon_cv
        starts_with_vc_block = starts_with_vc_block or initial_vc_count >= 2
        has_unprefixed_pitch_suffix = has_unprefixed_pitch_suffix or (
            segment_unprefixed and segment_attached_pitch
        )
        has_unprefixed_pitch_yoon_first_gap = has_unprefixed_pitch_yoon_first_gap or (
            segment_unprefixed and segment_attached_pitch and segment_yoon_cv
        )
        has_headless_pitch_suffix = has_headless_pitch_suffix or (
            segment_underscore and segment_attached_pitch
        )
        has_headless_soft_yoon_only = has_headless_soft_yoon_only or (
            segment_underscore
            and segment_soft_suffix
            and (segment_yoon_cv or bool(_cvvc_headless_yoon_only_onset_from_wav(wav)))
        )

        if (
            segment_unprefixed
            and not segment_attached_pitch
            and roles
            and roles[0] == "cv_head"
        ):
            head_phones = tuple(_cvvc_initial_cv_head_phone_sequence(segment[0].alias))
            head_phone = str(head_phones[0]).strip().lower() if head_phones else ""
            if head_phone in JAPANESE_CVVC_UNPREFIXED_OBSTRUENT_GRID_PHONES:
                unprefixed_obstruent_head = True

        for row, role in zip(segment, roles):
            if role != "vc":
                continue
            left_phones = _alias_token_phones_allow_numeric_suffix(_cvvc_vc_alias_left_token(row.alias))
            right_head = _cvvc_vc_alias_right_head_phone(row.alias)
            if left_phones == ["n"] and right_head in {"w", "y"}:
                has_tail_moraic_n_glide_vc = True
                break

        segment_start = segment_end

    return JaCvvcRepairDispatch(
        underscore_wav=underscore_wav,
        unprefixed_wav=unprefixed_wav,
        has_attached_pitch_suffix=has_attached_pitch_suffix,
        has_separated_soft_suffix=has_separated_soft_suffix,
        has_yoon_cv=has_yoon_cv,
        starts_with_vc_block=starts_with_vc_block,
        has_tail_moraic_n_glide_vc=has_tail_moraic_n_glide_vc,
        unprefixed_obstruent_head=unprefixed_obstruent_head,
        has_unprefixed_pitch_suffix=has_unprefixed_pitch_suffix,
        has_unprefixed_pitch_yoon_first_gap=has_unprefixed_pitch_yoon_first_gap,
        has_headless_pitch_suffix=has_headless_pitch_suffix,
        has_headless_soft_yoon_only=has_headless_soft_yoon_only,
    )


def repair_cvvc_row_sequence(
    rows: Sequence[AdaptedOtoRow],
    config: OtoAdapterConfig | None = None,
    *,
    file_duration_ms: float | None = None,
    posterior: FramePosterior | None = None,
) -> list[AdaptedOtoRow]:
    cfg = config or OtoAdapterConfig()
    out = repair_cvvc_vc_row_sequence(rows, cfg)
    if _is_korean_cvc_config(cfg):
        out = _repair_korean_cvc_release_cluster_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_obstruent_vc_from_previous_cv_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_internal_obstruent_vc_midpoint_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_liquid_vc_from_previous_cv_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_r_liquid_vc_next_cv_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_nasal_ng_vc_from_neighbor_cv_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_compact_cv_sequence_gap_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_initial_cv_onset_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_compact_cv_sequence_gap_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_initial_local_gap_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_late_plain_cv_suffix_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_initial_nasal_ng_pair_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_pure_v_glide_sequence_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_midrow_vc_neighbor_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_initial_block_collapse_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_compressed_cv_vc_cv_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_spaced_obstruent_cadence_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_terminal_cv_before_spaced_vc_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_internal_i_k_midpoint_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_alternating_cv_profile_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_no_space_vc_cadence_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_default_cv_midpoint_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_nasal_vc_pair_cadence_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_sonorant_cv_profile_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_liquid_yoon_cv_profile_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_spaced_t_vc_after_profile_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_compact_k_vc_after_profile_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_compact_l_vc_after_profile_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_standalone_vowel_start_profile_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_cv_cutoff_before_next_row_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_glide_cv_cutoff_before_next_row_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_doubled_cv_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_plain_obstruent_cv_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_residual_glide_cv_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_head_glide_cv_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_sonorant_liquid_cv_huge_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_mn_glide_cv_huge_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_tail_weo_cv_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_tail_wi_cv_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_tail_yoon_cv_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_tail_eui_cv_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_residual_plain_doubled_v_vc_cutoff_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_residual_exact_profile_rows(
            out,
            cfg,
            file_duration_ms=file_duration_ms,
        )
        out = _repair_korean_cvc_terminal_spaced_obstruent_vc_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_terminal_obstruent_vc_rows(out, cfg, file_duration_ms=file_duration_ms)
        out = _repair_korean_cvc_pitch_suffix_grid_profile_rows(out, cfg, file_duration_ms=file_duration_ms)
        return _repair_oto_parameter_order_rows(out, file_duration_ms=file_duration_ms)
    if not _is_japanese_cvvc_config(cfg):
        return _repair_oto_parameter_order_rows(out, file_duration_ms=file_duration_ms)
    dispatch = _ja_cvvc_repair_dispatch(out, cfg)
    out = _repair_cvvc_initial_spaced_cv_rows(out, cfg)
    out = _repair_cvvc_initial_vowel_cv_head_rows(out, cfg)
    out = _repair_cvvc_initial_consonant_cv_head_rows(out, cfg)
    out = _repair_cvvc_initial_consonant_cv_head_profile_rows(out, cfg)
    out = _repair_cvvc_pure_vowel_sequence_rows(out, cfg)
