def _is_korean_cvc_glide_cv_alias(alias: str, config: OtoAdapterConfig) -> bool:
    raw = str(alias or "")
    if not raw or raw.strip() != raw or re.search(r"\s", raw):
        return False
    if _is_terminal_silence_alias(raw) or _is_nonphonetic_special_alias(raw):
        return False
    alias_type = _alias_type_for_row(raw, config.alias_type)
    if alias_type == "v":
        phones = tuple(str(phone or "").strip().lower() for phone in _alias_phone_sequence(raw))
        return len(phones) == 1 and phones[0] in KOREAN_CVC_GLIDE_CV_CUTOFF_VOWELS
    if alias_type != "cv":
        return False
    phones = tuple(str(phone or "").strip().lower() for phone in _alias_phone_sequence(raw))
    if not phones:
        return False
    if any(phone in KOREAN_CVC_GLIDE_CV_CUTOFF_MEDIALS for phone in phones):
        return True
    return any(phone in KOREAN_CVC_GLIDE_CV_CUTOFF_VOWELS for phone in phones)


