def _is_korean_cvc_doubled_plain_cv_alias(alias: str, config: OtoAdapterConfig) -> bool:
    raw = str(alias or "")
    if not raw or raw.strip() != raw or re.search(r"\s", raw):
        return False
    if _is_terminal_silence_alias(raw) or _is_nonphonetic_special_alias(raw):
        return False
    if _alias_type_for_row(raw, config.alias_type) != "cv":
        return False
    phones = tuple(str(phone or "").strip().lower() for phone in _alias_phone_sequence(raw))
    if len(phones) != 3:
        return False
    if phones[0] != phones[1]:
        return False
    if is_vowel_phone(phones[0], "korean"):
        return False
    if phones[2] in KOREAN_CVC_GLIDE_CV_CUTOFF_VOWELS:
        return False
    return is_vowel_phone(phones[2], "korean")


def _repair_korean_cvc_plain_obstruent_cv_cutoff_profile_rows(
    rows: Sequence[AdaptedOtoRow],
    config: OtoAdapterConfig,
    *,
    file_duration_ms: float | None = None,
) -> list[AdaptedOtoRow]:
    if not _is_korean_cvc_config(config):
        return list(rows)
    out = list(rows)
    segment_start = 0
    while segment_start < len(out):
        wav_key = str(out[segment_start].wav or "").strip().lower()
        segment_end = segment_start + 1
        while segment_end < len(out) and str(out[segment_end].wav or "").strip().lower() == wav_key:
            segment_end += 1
        for index in range(segment_start, segment_end - 1):
            out[index] = _repair_korean_cvc_plain_obstruent_cv_cutoff_profile_row(
                out[index],
                out[index + 1],
                config,
                row_index_in_wav=index - segment_start,
                file_duration_ms=file_duration_ms,
            )
        segment_start = segment_end
    return out


def _repair_korean_cvc_plain_obstruent_cv_cutoff_profile_row(
    row: AdaptedOtoRow,
    following: AdaptedOtoRow,
    config: OtoAdapterConfig,
    *,
    row_index_in_wav: int,
    file_duration_ms: float | None = None,
) -> AdaptedOtoRow:
    if int(row_index_in_wav) < int(KOREAN_CVC_PLAIN_OBSTRUENT_CV_CUTOFF_MIN_ROW_INDEX):
        return row
    if not _is_korean_cvc_plain_obstruent_cv_alias(row.alias, config):
        return row
    if float(row.timing.cutoff) >= 0.0:
        return row
    if float(row.timing.preutterance) > float(KOREAN_CVC_PLAIN_OBSTRUENT_CV_CUTOFF_MAX_PRE_MS):
        return row
    if float(row.timing.overlap) > float(KOREAN_CVC_PLAIN_OBSTRUENT_CV_CUTOFF_MAX_OVERLAP_MS):
        return row

    cutoff_abs = abs(float(row.timing.cutoff))
    target_cutoff_abs = float(KOREAN_CVC_PLAIN_OBSTRUENT_CV_CUTOFF_PROFILE_MS)
    if cutoff_abs < float(KOREAN_CVC_PLAIN_OBSTRUENT_CV_CUTOFF_TRIGGER_MS):
        return row
    if cutoff_abs > float(KOREAN_CVC_PLAIN_OBSTRUENT_CV_CUTOFF_MAX_CURRENT_MS):
        return row
    if cutoff_abs <= target_cutoff_abs + float(KOREAN_CVC_PLAIN_OBSTRUENT_CV_CUTOFF_MIN_DELTA_MS):
        return row

    offset = float(row.timing.offset)
    next_offset = float(following.timing.offset)
    next_gap = next_offset - offset
    if next_gap < float(KOREAN_CVC_PLAIN_OBSTRUENT_CV_CUTOFF_MIN_NEXT_GAP_MS):
        return row
    if next_gap > float(KOREAN_CVC_PLAIN_OBSTRUENT_CV_CUTOFF_MAX_NEXT_GAP_MS):
        return row

    timing = OtoTiming(
        offset=offset,
        consonant=float(row.timing.consonant),
        cutoff=-target_cutoff_abs,
        preutterance=float(row.timing.preutterance),
        overlap=float(row.timing.overlap),
    )
    timing, timing_warnings = _validate_timing_with_warnings(timing, file_duration_ms=file_duration_ms)
    warnings = (
        *row.warnings,
        f"korean_cvc_plain_obstruent_cv_cutoff_profile_capped:{cutoff_abs:.1f}->{abs(timing.cutoff):.1f}",
        f"korean_cvc_plain_obstruent_cv_cutoff_profile_next_gap:{next_gap:.1f}",
        *timing_warnings,
    )
    anchor = row.anchor
    if anchor is not None:
        anchor = replace(
            anchor,
            warnings=tuple(dict.fromkeys((*anchor.warnings, *warnings))),
        )
    return replace(
        row,
        timing=timing,
        anchor=anchor,
        warnings=tuple(dict.fromkeys(warnings)),
        applied_rules=tuple(
            dict.fromkeys((*row.applied_rules, "korean_cvc_plain_obstruent_cv_cutoff_profile_repair"))
        ),
    )


def _is_korean_cvc_plain_obstruent_cv_alias(alias: str, config: OtoAdapterConfig) -> bool:
    raw = str(alias or "")
    if not raw or raw.strip() != raw or re.search(r"\s", raw):
        return False
    if _is_terminal_silence_alias(raw) or _is_nonphonetic_special_alias(raw):
        return False
    if _alias_type_for_row(raw, config.alias_type) != "cv":
        return False
    phones = tuple(str(phone or "").strip().lower() for phone in _alias_phone_sequence(raw))
    if len(phones) != 2:
        return False
    onset, vowel = phones
    if onset in KOREAN_CVC_PLAIN_OBSTRUENT_CV_CUTOFF_EXCLUDED_ONSETS:
        return False
    if is_vowel_phone(onset, "korean"):
        return False
    if not is_vowel_phone(vowel, "korean"):
        return False
    if any(phone in KOREAN_CVC_GLIDE_CV_CUTOFF_MEDIALS for phone in phones):
        return False
    return vowel not in KOREAN_CVC_GLIDE_CV_CUTOFF_VOWELS


